#!/usr/bin/env python3
"""Generate the Nash website and search index from the maintained handbook."""
from pathlib import Path
import html, json, re, shutil
import markdown
ROOT=Path(__file__).resolve().parents[1]
DIST=ROOT/'dist';CONTENT=ROOT/'content'
REPO='https://github.com/nihitdev/nash-shell'
PAGES=[('start','GETTING-STARTED.md','Getting started','Installation and your first session','Start here'),('configuration','CONFIGURATION.md','Configuration','Make config.nash your own','Start here'),('aliases','ALIASES.md','Aliases & shortcuts','Everyday commands, fewer keystrokes','Start here'),('tools','TOOLS.md','Tool integration guide','Bring your favorite tools','Start here'),('keybindings','KEYBINDINGS.md','Editing & keybindings','Completion, history and keyboard controls','Using Nash'),('troubleshooting','TROUBLESHOOTING.md','Troubleshooting','Answers to common issues','Using Nash'),('architecture','ARCHITECTURE.md','Architecture','How the shell is built','Development'),('integrations','INTEGRATIONS.md','Integration contracts','Lifecycle hooks and native adapters','Development'),('testing','TESTING.md','Testing','Build checks, PTYs and sanitizers','Development'),('benchmarks','BENCHMARKS.md','Benchmarks','Recorded measurements and methodology','Development'),('attribution','ATTRIBUTION.md','Provenance & attribution','Our ang.sh roots and MIT license','Development'),('reliability','RELIABILITY.md','Command reliability','Reproduced failures, fixes and regression coverage','Development')]
TOOLS=[('fastfetch','Fastfetch','System information','native','Startup adapter','A system-information banner when Nash opens.','config set integrations.fastfetch.enabled true'),('eza','Eza','Directory listings','native','Managed shortcuts','Readable listings, icons, and a directory tree.','config set integrations.eza.enabled true'),('bat','Bat','File viewing','native','Managed shortcuts','Syntax-highlighted viewing, without replacing cat.','config set integrations.bat.enabled true'),('starship','Starship','Prompt engine','native','Native prompt','Keep the Starship configuration you already use.','config set prompt.engine starship'),('git','Git','Version control','external','External CLI','Status, diff, log, and familiar aliases.','alias gs=\'git status --short\''),('zoxide','Zoxide','Directory navigation','recipe','Hook recipe','Record visited directories through a chpwd hook.','has zoxide && config hook chpwd \'zoxide add "$PWD"\''),('fzf','FZF','Fuzzy selection','external','External CLI','Pipe a list into an interactive fuzzy finder.','find . -type f | fzf'),('yazi','Yazi','File manager','external','External CLI','Explore your files in a foreground terminal UI.','has yazi && alias y=\'yazi\''),('atuin','Atuin','History search','planned','Native adapter pending','Use the CLI; native history recording is not wired in.','atuin search'),('direnv','Direnv','Environment management','planned','Native adapter pending','Inspect status; automatic environment import is pending.','direnv status'),('prism','Prism','Terminal themes','external','External CLI','Use your installed theme CLI; palette sync is pending.','prism --help'),('yoo','yoo','Developer workspace','external','External CLI','Run your developer tools directly from Nash.','yoo --help')]
LINKS={f:('/docs/'+s+'.html') for s,f,*_ in PAGES}|{'README.md':'/docs/index.html','../CONTRIBUTING.md':'/docs/contributing.html','../examples/config.nash':'/examples/config.nash','CONFIGURATION.md':'/docs/configuration.html','benchmark-results.json':'/benchmark-results.json'}
def esc(s):return html.escape(str(s),quote=True)
def icon(name):
 paths={'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>','arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>','sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>','copy':'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 4H5v13"/>','menu':'<path d="M4 6h16M4 12h16M4 18h16"/>','close':'<path d="m5 5 14 14M19 5 5 19"/>','external':'<path d="M14 4h6v6m0-6L10 14M10 5H5v15h15v-5"/>'}
 return '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+paths.get(name,paths['arrow'])+'</svg>'
def doc_url(s):return '/docs/'+s+'.html'
def rewrite(md):
 def link(m):
  label,target=m.groups();base,sep,anchor=target.partition('#')
  if base.startswith(('http:','https:','mailto:')) or not base:return m.group(0)
  mapped=LINKS.get(base)
  if not mapped:
   filename=Path(base).name
   mapped=LINKS.get(filename)
  if not mapped:mapped=REPO+'/blob/main/'+base.removeprefix('../')
  return '['+label+']('+mapped+('#'+anchor if sep else '')+')'
 return re.sub(r'\[([^\]]*)\]\(([^)]+)\)',link,md)
def md_html(md):
 engine=markdown.Markdown(extensions=['fenced_code','tables','toc','sane_lists'],extension_configs={'toc':{'permalink':False}})
 body=engine.convert(rewrite(md));return body,engine.toc

def shell(title,body,active='home',desc='',toc='',sidebar=''):
 nav=''.join(f'<a class="{"active" if active==key else ""}" href="{url}"'+(' aria-current="page"' if active==key else '')+f'>{label}</a>' for key,url,label in [('home','/','Home'),('docs','/docs/','Documentation'),('tools','/tools.html','Tools'),('development','/docs/architecture.html','Development')])
 content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="{esc(desc or 'Nash Shell: a customizable C++23 Unix shell with native prompts, config.nash and optional tools.')}"><title>{esc(title)} · Nash Shell</title><link rel="icon" href="/assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a class="brand" href="/" aria-label="Nash Shell home"><img src="/assets/mark.svg" alt="" width="39" height="39"><span>nash<span class="brand-light">shell</span></span></a><nav class="top-nav" aria-label="Main navigation">{nav}</nav><div class="header-actions"><button class="search-trigger" data-search-open aria-label="Search documentation">{icon('search')}<span>Search docs</span><kbd>/</kbd></button><button class="icon-button theme-toggle" aria-label="Toggle color theme">{icon('sun')}</button><a class="github-link" href="{REPO}" aria-label="Nash source on GitHub">GitHub {icon('external')}</a><button class="icon-button mobile-toggle" aria-label="Toggle navigation" aria-expanded="false">{icon('menu')}</button></div></div></header><div class="subbar"><div class="container"><span><span class="status-dot"></span>v0.2.0 <span class="muted-dot">/</span> Early development <span class="muted-dot">/</span> Linux-first</span><a href="/changelog.html">What’s new {icon('arrow')}</a></div></div>{body}<footer class="site-footer"><div class="container footer-grid"><div><a class="footer-brand" href="/">nash<span>shell</span></a><p>A shell you can make your own.</p><p class="fine">Maintained by <a href="https://github.com/nihitdev">nihitdev</a> · MIT licensed</p></div><div><h2>The project</h2><a href="{REPO}">Source code</a><a href="{REPO}/issues">Report an issue</a><a href="/docs/contributing.html">Contribute</a></div><div><h2>Find your way</h2><a href="/docs/start.html">Installation</a><a href="/docs/configuration.html">Configuration</a><a href="/tools.html">Tool support</a></div><div class="footer-note"><p>Nash is an attributed fork of <a href="https://github.com/0x251C08/ang.sh">ang.sh</a>.</p><p>Independent project. Not affiliated with Arch Linux.</p><a href="/docs/attribution.html">Provenance & licenses {icon('arrow')}</a></div></div></footer><dialog class="search-dialog" aria-labelledby="search-title"><div class="search-box"><div class="search-input-row">{icon('search')}<label class="sr-only" for="search-input" id="search-title">Search Nash documentation</label><input id="search-input" type="search" placeholder="Search guides, settings, tools…" autocomplete="off"><button class="icon-button" data-search-close aria-label="Close search">{icon('close')}</button></div><div id="search-results" aria-live="polite"><p class="search-hint">Try “fastfetch”, “aliases”, or “prompt.engine”.</p></div><div class="search-footer"><span>↑ ↓ to navigate · Enter to open</span><span>Esc to close</span></div></div></dialog><div id="toast" role="status" aria-live="polite"></div></body></html>'''
 return content

def write(path,content):
 dest=DIST/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
def sidebar(current=''):
 parts=['<aside class="docs-sidebar" aria-label="Documentation navigation"><a class="sidebar-title" href="/docs/">Nash handbook</a>'];group=None
 for slug,_,label,_,section in PAGES:
  if section!=group:parts.append('<h2>'+section+'</h2>');group=section
  parts.append(f'<a href="{doc_url(slug)}"'+(' class="selected" aria-current="page"' if slug==current else '')+'>'+label+'</a>')
 parts.append('<h2>Project</h2><a href="/docs/contributing.html">Contributing</a><a href="/changelog.html">Changelog</a><a href="'+REPO+'">GitHub ↗</a></aside>');return ''.join(parts)

def main():
 source=ROOT.parent/'docs'
 if source.is_dir():
  CONTENT.mkdir(exist_ok=True)
  for p in source.glob('*.md'):shutil.copy2(p,CONTENT/p.name)
  for name in ['CONTRIBUTING.md','SECURITY.md','CHANGELOG.md']:
   shutil.copy2(ROOT.parent/name,CONTENT/name)
  shutil.copy2(ROOT.parent/'examples/config.nash',CONTENT/'config.nash')
  shutil.copy2(source/'benchmark-results.json',CONTENT/'benchmark-results.json')
 DIST.mkdir(exist_ok=True)
 shutil.copytree(ROOT/'assets',DIST/'assets',dirs_exist_ok=True)
 (DIST/'examples').mkdir(exist_ok=True)
 shutil.copy2(CONTENT/'config.nash',DIST/'examples/config.nash')
 shutil.copy2(CONTENT/'benchmark-results.json',DIST/'benchmark-results.json')
 search=[]
 for slug,filename,title,desc,section in PAGES+[('contributing','CONTRIBUTING.md','Contributing','Help build Nash','Project'),('security','SECURITY.md','Security','Report a vulnerability responsibly','Project')]:
  md=(CONTENT/filename).read_text();md=re.sub(r'^# .+\n','',md,count=1);body,toc=md_html(md)
  article=f'''<main id="main" class="container docs-layout">{sidebar(slug)}<article class="doc-article"><div class="breadcrumbs"><a href="/docs/">Documentation</a><span>/</span>{esc(section)}</div><h1>{esc(title)}</h1><p class="article-lead">{esc(desc)}</p><div class="article-meta"><span>Handbook · v0.2.0</span><a href="{REPO}/blob/main/{'docs/' if filename not in ['CONTRIBUTING.md','SECURITY.md'] else ''}{filename}">View source {icon('external')}</a></div><div class="prose">{body}</div><div class="doc-bottom"><span>Something unclear? <a href="{REPO}/issues">Open an issue</a>.</span><a href="/docs/">Back to handbook ↑</a></div></article><aside class="page-outline"><span>On this page</span>{toc}<div class="outline-note">Trying Nash?<br><a href="/docs/start.html">Start with installation →</a></div></aside></main>'''
  write('docs/'+slug+'.html',shell(title,article,'docs',desc));search.append({'title':title,'url':doc_url(slug),'text':re.sub(r'[#*`\[\]()]',' ',md),'category':section})
 docs='''<main id="main" class="container docs-layout">'''+sidebar()+'''<article class="doc-article"><div class="breadcrumbs">Documentation <span>/</span> Handbook</div><h1>The Nash handbook</h1><p class="article-lead">Practical guides for your shell, configuration, and the tools you use every day.</p><div class="notice"><strong>Start here.</strong> Build Nash, open your first session, then make it yours with config.nash.</div><div class="guide-grid">'''
 for slug,_,title,desc,section in PAGES[:6]:docs+=f'<a class="guide-card" href="{doc_url(slug)}"><span class="eyebrow">{section}</span><h2>{title} {icon("arrow")}</h2><p>{desc}.</p></a>'
 docs+='''</div><h2>Built in the open</h2><p>Read the architecture, test strategy, benchmarks, and integration contracts. Current limitations are documented alongside working features.</p><a class="text-link" href="/docs/architecture.html">Explore the internals →</a></article><aside class="page-outline"><span>Need a command?</span><button class="outline-search" data-search-open>Search the handbook /</button><div class="outline-note">Source-first documentation. Every guide comes from the maintained repository.</div></aside></main>'''
 write('docs/index.html',shell('Documentation',docs,'docs'))
 render_home();render_tools();render_configurator()
 md=(CONTENT/'CHANGELOG.md').read_text();body,toc=md_html(md)
 write('changelog.html',shell('Changelog','<main id="main" class="container single-article"><div class="breadcrumbs">Project / Development</div><h1>Project changelog</h1><p class="article-lead">What changed, what works, and what comes next.</p><div class="notice">0.2.0 is unreleased. No release binaries or tags have been published.</div><div class="prose">'+body+'</div></main>','development'))
 write('404.html',shell('Page not found','<main id="main" class="container single-article"><span class="eyebrow">404 / PAGE NOT FOUND</span><h1>A wrong turn, not a dead end.</h1><p>Search the handbook or head back to the project home.</p><a class="button primary" href="/">Back to Nash →</a></main>'))
 write('search-index.json',json.dumps(search,ensure_ascii=False));write('robots.txt','User-agent: *\nAllow: /\n')
 print(f'Built {len(list(DIST.rglob("*.html")))} HTML pages and {len(search)} searchable guides.')

def render_home():
 body='''<main id="main" class="container home-layout"><div class="home-main"><section class="hero"><div class="eyebrow"><span class="tiny-line"></span> THE NASH SHELL PROJECT</div><h1>A shell of your own.</h1><p class="hero-lead">A familiar terminal. A native prompt. A configuration that speaks shell.</p><p class="hero-description">Nash is a customizable C++23 Unix shell with interactive editing and room for the tools you already use. Build it, open it, make it yours.</p><div class="hero-actions"><a class="button primary" href="/docs/start.html">Get started '''+icon('arrow')+'''</a><a class="button secondary" href="/docs/">Read the handbook</a></div><div class="hero-footnote">Linux-first <span>·</span> MIT licensed <span>·</span> No telemetry or daemon</div><div class="terminal"><div class="terminal-title"><div class="window-dots"><i></i><i></i><i></i></div><span>nash — ~/Projects</span><span class="terminal-label">Example session</span></div><div class="terminal-body"><div><span class="term-cyan">nash</span> <span class="term-blue">~/Projects</span> <span class="term-purple">⎇ main</span></div><div><span class="term-cyan">❯</span> <span class="term-green">config</span> set prompt.engine native</div><div class="terminal-spacer"></div><div><span class="term-cyan">❯</span> <span class="term-green">alias</span> gs=<span class="term-yellow">'git status --short'</span></div><div><span class="term-cyan">❯</span> <span class="term-green">echo</span> <span class="term-yellow">"hello, nash"</span> | tr a-z A-Z</div><div class="term-output">HELLO, NASH</div><div class="terminal-spacer"></div><div><span class="term-cyan">❯</span> <span class="term-green">config</span> set integrations.eza.enabled true</div><div><span class="term-cyan">❯</span> <span class="term-green">ll</span><span class="term-ghost"> ~/Projects</span><span class="terminal-cursor"></span></div></div></div></section><section class="project-news"><div class="section-header"><h2>From the project</h2><a href="/changelog.html">All changes →</a></div><article class="news-item"><time datetime="2026-11-06">06 NOV 2026</time><div><a href="/tools.html"><h3>Your everyday tools, closer to the shell.</h3></a><p>Opt-in Fastfetch startup and managed Eza/Bat shortcuts join the native Starship adapter. Explore support levels and copy working setup commands.</p><a class="text-link" href="/tools.html">Explore tool support →</a></div></article><article class="news-item"><time datetime="2026-11-05">05 NOV 2026</time><div><a href="/docs/configuration.html"><h3>Meet config.nash.</h3></a><p>One startup file, ordinary Nash commands. Settings, aliases, environment variables, hooks, and keybindings live together.</p><a class="text-link" href="/docs/configuration.html">Configure your shell →</a></div></article></section><section class="principles"><div><span class="feature-number">01</span><h3>Native by default</h3><p>A prompt of its own, with optional Starship when you want it.</p></div><div><span class="feature-number">02</span><h3>Understandable setup</h3><p>Readable commands and documented behavior, without a background service.</p></div><div><span class="feature-number">03</span><h3>Built in the open</h3><p>MIT source, tests, measured benchmarks, and honest limitations.</p></div></section></div><aside class="home-sidebar"><section class="side-panel getting-started"><span class="eyebrow">NEW TO NASH?</span><h2>A good place to start.</h2><a href="/docs/start.html"><span>01</span> Install & launch '''+icon('arrow')+'''</a><a href="/docs/configuration.html"><span>02</span> Create config.nash '''+icon('arrow')+'''</a><a href="/tools.html"><span>03</span> Add your tools '''+icon('arrow')+'''</a></section><section class="side-panel"><h2>Project status</h2><dl class="project-facts"><div><dt>Version</dt><dd>0.2.0 <span class="small-tag">unreleased</span></dd></div><div><dt>Platform</dt><dd>Linux</dd></div><div><dt>Language</dt><dd>C++23</dd></div><div><dt>License</dt><dd>MIT</dd></div></dl><p class="small-note">Early development. Try Nash in your current terminal; keep your login shell.</p></section><section class="side-panel compact-links"><h2>Useful reading</h2><a href="/docs/aliases.html">Aliases & everyday shortcuts →</a><a href="/docs/keybindings.html">Keyboard reference →</a><a href="/docs/troubleshooting.html">Something not working? →</a><a href="/docs/benchmarks.html">Actual benchmark results →</a></section><section class="side-panel support-panel"><span class="eyebrow">MAKE IT YOURS</span><h2>A little config goes a long way.</h2><p>Choose a prompt, a theme, and your optional tools. Get a ready-to-edit config file.</p><a class="button secondary full" href="/configure.html">Build your config '''+icon('arrow')+'''</a></section><a class="source-callout" href="'''+REPO+'''">Read the source<br><strong>nihitdev/nash-shell ↗</strong></a></aside></main>'''
 write('index.html',shell('Home',body))

def render_tools():
 body='''<main id="main" class="container tool-page"><div class="page-heading"><div><div class="eyebrow">THE NASH ECOSYSTEM</div><h1>Good tools. Clear support.</h1><p class="article-lead">Keep your favorites. See exactly how each one works with Nash.</p></div><a class="button secondary" href="/configure.html">Build your config →</a></div><div class="tool-toolbar"><div class="tool-search">'''+icon('search')+'''<label class="sr-only" for="tool-filter">Filter tools</label><input id="tool-filter" placeholder="Find a tool…" type="search"></div><div class="filter-pills" role="group" aria-label="Support level"><button class="selected" data-tool-category="all" aria-pressed="true">All tools</button><button data-tool-category="native" aria-pressed="false">Native support</button><button data-tool-category="recipe" aria-pressed="false">Hook recipes</button><button data-tool-category="planned" aria-pressed="false">Planned adapters</button></div><span id="tool-count" class="tool-count">12 tools</span></div><div class="tool-grid">'''
 full=(CONTENT/'TOOLS.md').read_text()
 sections=re.split(r'^## ',full,flags=re.M)[1:]
 for slug,name,category,kind,status,desc,command in TOOLS:
  body+=f'<a class="tool-card" href="/tools/{slug}.html" data-tool="{esc(name.lower()+" "+category.lower())}" data-kind="{kind}"><div class="tool-card-top"><span class="tool-monogram">{esc(name[:2].lower())}</span><span class="support-badge {kind}">{status}</span></div><span class="tool-category">{category}</span><h2>{name} {icon("arrow")}</h2><p>{desc}</p><code>{esc(command)}</code></a>'
  matching=next((x for x in sections if x.lower().startswith(name.lower()) or slug in ['prism','yoo'] and x.startswith('Prism and yoo')),None)
  md='## '+matching if matching else f'## {name}\n\n{desc}\n\n```sh\n{command}\n```\n'
  article,toc=md_html(md)
  detail=f'<main id="main" class="container docs-layout">{sidebar("tools")}<article class="doc-article"><div class="breadcrumbs"><a href="/tools.html">Tools</a><span>/</span>{name}</div><span class="support-badge {kind}">{status}</span><h1>{name}</h1><p class="article-lead">{desc}</p><div class="quick-command"><span>Quick setup</span><pre><code>{esc(command)}</code></pre></div><div class="prose">{article}</div><div class="doc-bottom"><a href="/tools.html">← All tools</a><a href="/configure.html">Build your config →</a></div></article><aside class="page-outline"><span>On this page</span>{toc}<div class="outline-note">Support is explicit.<br>CLI access does not imply a native adapter.</div></aside></main>'
  write('tools/'+slug+'.html',shell(name+' integration',detail,'tools',desc))
 body+='''</div><p class="empty-state" id="tool-empty" hidden>No tools match that search. Try a name or a different support filter.</p><div class="notice tool-note"><strong>What do support levels mean?</strong> Native features are implemented in Nash. Hook recipes are explicit configuration. External tools run normally, while planned adapters are not yet implemented.</div></main>'''
 write('tools.html',shell('Tools & integrations',body,'tools'))

def render_configurator():
 body='''<main id="main" class="container configure-page"><div class="eyebrow">CONFIG.NASH / YOUR STARTING POINT</div><h1>Make a little space your own.</h1><p class="article-lead">Choose your defaults. Copy the result into <code>~/.config/nash/config.nash</code>.</p><div class="config-layout"><form id="config-form" class="config-options"><fieldset><legend>01 <span>Your prompt</span></legend><label class="radio-option"><input type="radio" name="engine" value="native" checked><span><strong>Nash native</strong><small>The shell’s own prompt. No extra tool required.</small></span></label><label class="radio-option"><input type="radio" name="engine" value="starship"><span><strong>Starship</strong><small>Use your existing Starship configuration.</small></span></label></fieldset><fieldset><legend>02 <span>Your terminal tools</span></legend><label class="check-option"><input type="checkbox" name="fastfetch"><span><strong>Fastfetch at startup</strong><small>A banner once per interactive shell.</small></span></label><label class="check-option"><input type="checkbox" name="eza"><span><strong>Eza shortcuts</strong><small>ll, la, and lt — without replacing your aliases.</small></span></label><label class="check-option"><input type="checkbox" name="bat"><span><strong>Bat viewer</strong><small>view FILE with bat or batcat, paging disabled.</small></span></label></fieldset><fieldset><legend>03 <span>Everyday editing</span></legend><label class="check-option"><input type="checkbox" name="suggestions" checked><span>History autosuggestions</span></label><label class="check-option"><input type="checkbox" name="highlighting" checked><span>Syntax highlighting</span></label><label class="check-option"><input type="checkbox" name="completion" checked><span>Tab completion</span></label></fieldset></form><div class="config-preview"><div class="config-preview-head"><span>~/.config/nash/config.nash</span><span class="small-tag">live preview</span></div><pre><code id="config-output"></code></pre><div class="config-preview-actions"><button class="button primary" id="copy-config">Copy config '''+icon('copy')+'''</button><button class="button secondary" id="download-config">Download .nash</button></div><p>This generates text locally. It never reads or changes your machine. Tools stay optional; settings require a current Nash build.</p><a href="/docs/configuration.html">Read the complete configuration guide →</a></div></div></main>'''
 write('configure.html',shell('Build your config',body,'docs'))
if __name__=='__main__':main()
